(municipality_id, holiday_date, name_fr, name_en, name_zh, shift_days, sector, source_url) values
(current_setting('app.bb')::bigint, '2026-12-25', 'Noel', 'Christmas Day', '圣诞节', -1, 'all', current_setting('app.page')),
(current_setting('app.bb')::bigint, '2027-01-01', 'Jour de l''An', 'New Year''s Day', '元旦', -1, 'all', current_setting('app.page'));

